$user=fleet_cert_require_user();fleet_cert_require_same_origin_post();$db=fleet_db();$actor=(int)$user['id'];$in=json_decode((string)file_get_contents('php://input'),true);if(!is_array($in))json_response(['ok'=>false,'message'=>'Invalid repair work order request.'],400);
function work_event(PDO $db,int $order,int $actor,string $type,string $details,?string $old=null,?string $new=null):void{$q=$db->prepare('INSERT INTO maintenance_work_order_events(work_order_id,actor_id,event_type,details,old_status,new_status) VALUES(?,?,?,?,?,?)');$q->execute([$order,$actor,$type,$details,$old,$new]);}
try{$action=(string)($in['action']??'');fleet_cert_require_permission($user,'maintenance.work_orders');$db->beginTransaction();
 if($action==='create'){$asset=(int)($in['asset_id']??0);$summary=trim((string)($in['issue_summary']??''));$details=trim((string)($in['issue_details']??''));$priority=strtoupper(trim((string)($in['priority']??'NORMAL')));$due=trim((string)($in['target_completion_date']??''));if(!$asset||$summary===''||$details===''||mb_strlen($summary)>500||mb_strlen($details)>5000)throw new InvalidArgumentException('Select an asset and explain the fault and repair required (up to 5,000 characters).');if(!in_array($priority,['LOW','NORMAL','HIGH','URGENT'],true))throw new InvalidArgumentException('Choose a valid repair priority.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)||!checkdate((int)substr($due,5,2),(int)substr($due,8,2),(int)substr($due,0,4)))throw new InvalidArgumentException('Set a valid target completion date.');$q=$db->prepare('SELECT id FROM assets WHERE id=? AND is_active=1 FOR UPDATE');$q->execute([$asset]);if(!$q->fetchColumn())throw new InvalidArgumentException('Choose an active asset.');$q=$db->prepare("SELECT id FROM maintenance_work_orders WHERE asset_id=? AND status IN ('OPEN','IN_PROGRESS','REPAIR_COMPLETE') FOR UPDATE");$q->execute([$asset]);if($q->fetchColumn())throw new InvalidArgumentException('This asset already has an open repair work order. Update that work order instead.');$number='MW-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(4)));$q=$db->prepare('INSERT INTO maintenance_work_orders(work_order_number,asset_id,reported_by,issue_summary,issue_details,priority,target_completion_date) VALUES(?,?,?,?,?,?,?)');$q->execute([$number,$asset,$actor,$summary,$details,$priority,$due]);$id=(int)$db->lastInsertId();work_event($db,$id,$actor,'OPENED','Work order opened. Asset placed on maintenance hold.','', 'OPEN');fleet_cert_log($db,$actor,'OPEN_WORK_ORDER','MAINTENANCE_WORK_ORDER',$id,'Opened '.$number.' for asset '.$asset.': '.$summary);$db->commit();json_response(['ok'=>true,'message'=>'Repair work order opened. The asset is now blocked from trips until repaired, inspected, declared serviceable, and closed.','work_order_number'=>$number]);}
 $id=(int)($in['id']??0);if(!$id)throw new InvalidArgumentException('Choose a repair work order.');$q=$db->prepare('SELECT * FROM maintenance_work_orders WHERE id=? FOR UPDATE');$q->execute([$id]);$w=$q->fetch();if(!$w||in_array($w['status'],['CLOSED','CANCELLED'],true))throw new InvalidArgumentException('This work order is already closed or unavailable.');$old=(string)$w['status'];
 if($action==='update'){$summary=trim((string)($in['issue_summary']??''));$details=trim((string)($in['issue_details']??''));$priority=strtoupper(trim((string)($in['priority']??'')));$due=trim((string)($in['target_completion_date']??''));$notes=trim((string)($in['repair_notes']??''));if($summary===''||$details===''||mb_strlen($summary)>500||mb_strlen($details)>5000||mb_strlen($notes)>5000)throw new InvalidArgumentException('Enter a clear issue description, repair details, and notes.');if(!in_array($priority,['LOW','NORMAL','HIGH','URGENT'],true))throw new InvalidArgumentException('Choose a valid repair priority.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$due)||!checkdate((int)substr($due,5,2),(int)substr($due,8,2),(int)substr($due,0,4)))throw new InvalidArgumentException('Set a valid target completion date.');$q=$db->prepare('UPDATE maintenance_work_orders SET issue_summary=?,issue_details=?,priority=?,target_completion_date=?,repair_notes=? WHERE id=? AND status NOT IN (\'CLOSED\',\'CANCELLED\')');$q->execute([$summary,$details,$priority,$due,$notes?:null,$id]);$changeText='Work order updated. Issue: '.$summary.'; priority: '.$priority.'; target completion: '.$due.'.';if($notes!=='')$changeText.="\nRepair update: ".$notes;work_event($db,$id,$actor,'UPDATED',$changeText,$old,$old);fleet_cert_log($db,$actor,'UPDATE_WORK_ORDER','MAINTENANCE_WORK_ORDER',$id,'Updated work order '.$w['work_order_number'].'.');$db->commit();json_response(['ok'=>true,'message'=>'Repair work order updated. The maintenance hold remains active.']);}
 if($action==='start') {if($old!=='OPEN')throw new InvalidArgumentException('Only an open work order can be started.');$db->prepare("UPDATE maintenance_work_orders SET status='IN_PROGRESS' WHERE id=?")->execute([$id]);work_event($db,$id,$actor,'STARTED','Repair work started.',$old,'IN_PROGRESS');$db->commit();json_response(['ok'=>true,'message'=>'Repair marked in progress. The asset remains blocked from trips.']);}
 if($action==='repair_complete'){if($old!=='IN_PROGRESS')throw new InvalidArgumentException('Start the work order before marking the repair complete.');$notes=trim((string)($in['repair_notes']??''));if($notes===''||mb_strlen($notes)>5000)throw new InvalidArgumentException('Describe the repair work performed before continuing.');$db->prepare("UPDATE maintenance_work_orders SET status='REPAIR_COMPLETE',repair_completed_at=NOW(),repair_notes=? WHERE id=?")->execute([$notes,$id]);work_event($db,$id,$actor,'REPAIR_COMPLETE','Repair reported complete: '.$notes,$old,'REPAIR_COMPLETE');fleet_cert_log($db,$actor,'REPAIR_COMPLETE','MAINTENANCE_WORK_ORDER',$id,'Reported repair complete for '.$w['work_order_number'].'. Inspection and serviceable closure still required.');$db->commit();json_response(['ok'=>true,'message'=>'Repair completion recorded. The asset stays on hold until a passing post-repair inspection and serviceable closure.']);}
 if($action==='close'){if($old!=='REPAIR_COMPLETE')throw new InvalidArgumentException('Record repair completion before closing the work order.');if(empty($in['serviceable']))throw new InvalidArgumentException('Confirm the asset is serviceable after repair.');$q=$db->prepare("SELECT id FROM vehicle_inspections WHERE asset_id=? AND result='PASS' AND critical_defects=0 AND checked_at>GREATEST(?,COALESCE((SELECT MAX(COALESCE(resolved_at,reported_at)) FROM maintenance_logs WHERE asset_id=?),?)) AND id=(SELECT MAX(id) FROM vehicle_inspections WHERE asset_id=?) ORDER BY id DESC LIMIT 1");$q->execute([(int)$w['asset_id'],(string)$w['repair_completed_at'],(int)$w['asset_id'],(string)$w['repair_completed_at'],(int)$w['asset_id']]);$inspection=(int)$q->fetchColumn();if(!$inspection)throw new InvalidArgumentException('A fresh passing inspection recorded after repair completion is required before closure.');$q=$db->prepare('SELECT COUNT(*) FROM maintenance_logs WHERE asset_id=? AND resolved_at IS NULL');$q->execute([(int)$w['asset_id']]);if((int)$q->fetchColumn()>0)throw new InvalidArgumentException('Resolve all open defect-log items and record a fresh passing inspection before closing this work order.');$notes=trim((string)($in['closure_notes']??''));if(mb_strlen($notes)>1000)throw new InvalidArgumentException('Closure notes are too long.');$db->prepare("UPDATE maintenance_work_orders SET status='CLOSED',closed_by=?,closed_at=NOW(),final_inspection_id=?,repair_notes=CONCAT(COALESCE(repair_notes,''),?) WHERE id=?")->execute([$actor,$inspection,$notes!==''?"\nClosure: ".$notes:'',$id]);work_event($db,$id,$actor,'CLOSED','Asset declared serviceable and work order closed. Final passing inspection #'.$inspection.'.'.($notes?' '.$notes:''),$old,'CLOSED');fleet_cert_log($db,$actor,'CLOSE_WORK_ORDER','MAINTENANCE_WORK_ORDER',$id,'Declared asset '.$w['asset_id'].' serviceable and closed work order '.$w['work_order_number'].' after passing inspection '.$inspection.'.');$db->commit();json_response(['ok'=>true,'message'=>'Asset declared serviceable. Work order closed and maintenance hold released.']);}
 throw new InvalidArgumentException('Choose a valid repair work order action.');
}catch(InvalidArgumentException $e){if($db->inTransaction())$db->rollBack();json_response(['ok'=>false,'message'=>$e->getMessage()],400);}catch(Throwable $e){if($db->inTransaction())$db->rollBack();error_log('Repair work order update: '.$e->getMessage());json_response(['ok'=>false,'message'=>'The repair work order could not be saved. No changes were applied.'],500);}
